import pyomo.environ as pyo

DATA = {
    "EarliestLanding": [1, 3, 5],
    "LatestLanding": [10, 12, 15],
    "TargetLanding": [4, 8, 14],
    "PenaltyAfterTarget": [10, 20, 30],
    "PenaltyBeforeTarget": [5, 10, 15],
    "SeparationTime": [
        [0, 2, 3],
        [2, 0, 4],
        [3, 4, 0],
    ],
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA

    n = len(d["EarliestLanding"])
    aircraft = list(range(n))

    model = pyo.ConcreteModel()

    # Set of aircraft
    model.Aircraft = pyo.Set(initialize=aircraft, ordered=True)

    # Decision variable: actual landing time for each aircraft
    def landing_bounds(m, i):
        return (d["EarliestLanding"][i], d["LatestLanding"][i])

    model.landing_time = pyo.Var(
        model.Aircraft,
        domain=pyo.NonNegativeReals,
        bounds=landing_bounds,
    )

    # Deviation variables
    model.before_dev = pyo.Var(model.Aircraft, domain=pyo.NonNegativeReals)
    model.after_dev = pyo.Var(model.Aircraft, domain=pyo.NonNegativeReals)

    # Objective: minimize total weighted deviation from target times
    def obj_rule(m):
        return sum(
            d["PenaltyBeforeTarget"][i] * m.before_dev[i]
            + d["PenaltyAfterTarget"][i] * m.after_dev[i]
            for i in m.Aircraft
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Target deviation constraint: landing = target - before + after
    def target_deviation_rule(m, i):
        return m.landing_time[i] == (
            d["TargetLanding"][i] - m.before_dev[i] + m.after_dev[i]
        )

    model.target_deviation = pyo.Constraint(
        model.Aircraft, rule=target_deviation_rule
    )

    # Separation / order constraint between consecutive aircraft in fixed order
    def separation_rule(m, i):
        # aircraft i precedes aircraft i+1
        return (
            m.landing_time[i + 1]
            >= m.landing_time[i] + d["SeparationTime"][i][i + 1]
        )

    model.separation = pyo.Constraint(
        range(n - 1), rule=separation_rule
    )

    return model
